/** Macro class host: the `macro class` expression holds the members. */
class MacroClassHost {
	static var counter:Int = 0;
	static function main() {}
	static function build():haxe.macro.Expr.TypeDefinition {
		return macro class {
			var a:Int;
			var b:String;
			static var counter:Int = 0;


			@:keep var c:Int;
			@:keep
			@:native("e") var e:Int;
			public function new() {
				a = 1;
			}
			// line comment run
			/* block comment */
			// second line comment
			function brace(x:Int):Int {
				if (x > 0) return 1;
				else return 0;
			}
			function braceLeft(x:Int):Int
			{
				if (x > 0)
				{
					a = 1;
				}
				else
				{
					a = 2;
				};
				return a; // trailing
			}
			public static function longSignature(firstArgument:String, secondArgument:Array<String>, thirdArgument:Map<String, Int>, fourthArgument:Int = 0):Void {
				trace(firstArgument, secondArgument, thirdArgument, fourthArgument, "a long literal string one", "another long literal string two");
			}
		};
	}
}

