/** Abstract host: from/to casts, operators, forwarding. */
@:forward
abstract AbstractHost(Int) from Int to Int {
	static var counter:Int = 0;
	static var other:Int = 1;
	public inline function new(v:Int) {
		this = v;
	}


	/** Doc comment before a function. */
	@:from static function fromString(s:String):AbstractHost return new AbstractHost(s.length);
	@:to function toStr():String return Std.string(this);
	@:op(A + B) static function add(lhs:AbstractHost, rhs:AbstractHost):AbstractHost return new AbstractHost(lhs.get() + rhs.get());
	@:keep
	@:op(A - B)
	static function sub(lhs:AbstractHost, rhs:AbstractHost):AbstractHost {
		return new AbstractHost(lhs.get() - rhs.get());
	}

	// line comment run
	/* block comment */
	// second line comment
	function get():Int
	{
		if (this > 0)
		{
			return this;
		}
		else return 0;
	}
	function elseSemi():Int {
		if (this > 0) {
			return 1;
		} else {
			return 2;
		};
	}
	public static function longSignature(firstArgument:String, secondArgument:Array<String>, thirdArgument:Map<String, Int>, fourthArgument:Int = 0, fifthArgument:Bool = false):Void {
		trace(firstArgument, secondArgument, thirdArgument, fourthArgument, fifthArgument, "a long literal string one", "another long literal string two");
	}
	static function main() {}
}

